import React, { createContext, useContext, useState } from 'react';

const NeuralContext = createContext();

export const NeuralProvider = ({ children }) => {
  const [neuralState, setNeuralState] = useState({
    isProcessing: false,
    neuralMode: 'standard',
    performanceLevel: 'optimal'
  });

  const value = {
    neuralState,
    setNeuralState,
    // Add more neural-related functions here as needed
  };

  return (
    <NeuralContext.Provider value={value}>
      {children}
    </NeuralContext.Provider>
  );
};

export const useNeural = () => {
  const context = useContext(NeuralContext);
  if (!context) {
    throw new Error('useNeural must be used within a NeuralProvider');
  }
  return context;
}; 