import React, { createContext, useContext, useState, useEffect } from 'react';
import { 
  getCurrentUser,
  onAuthStateChange,
  signIn,
  signUp,
  signInWithGoogle,
  signOut,
  saveUserProfile,
  saveTasks,
  deleteTask,
  saveStudySession,
  getStudyData,
  getTasks
} from '../lib/supabase';

// Create auth context
const AuthContext = createContext();

// Auth provider component
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isNewUser, setIsNewUser] = useState(false);
  const [onboardingCompleted, setOnboardingCompleted] = useState(false);
  const [isOfflineMode, setIsOfflineMode] = useState(false);

  // Load user on initial render
  useEffect(() => {
    // Check for initial user
    getCurrentUser().then(({ user, offline }) => {
      if (offline) setIsOfflineMode(true);
      
      if (user) {
        setUser(user);
        setOnboardingCompleted(user.profile?.onboarding_completed || false);
      }
      setLoading(false);
    });

    // Subscribe to auth changes
    const unsubscribe = onAuthStateChange((user) => {
      setUser(user);
      if (user) {
        setOnboardingCompleted(user.profile?.onboarding_completed || false);
      }
      setLoading(false);
    });

    // Clean up subscription on unmount
    return () => {
      if (typeof unsubscribe === 'function') {
        unsubscribe();
      }
    };
  }, []);

  // Update user data in database
  const updateUserData = async (data) => {
    if (!user) return { success: false, error: 'No user logged in' };
    
    try {
      const { data: responseData, error, offline } = await saveUserProfile(user.id, data);
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Update local user state
      setUser(prevUser => ({
        ...prevUser,
        profile: {
          ...prevUser.profile,
          ...data
        }
      }));
      
      return { success: true };
    } catch (error) {
      console.error('Error updating user data:', error);
      return { success: false, error };
    }
  };

  // Add or update a task
  const addOrUpdateTask = async (task) => {
    if (!user) return { success: false, error: 'No user logged in' };
    
    try {
      // Get current tasks first
      const tasksResponse = await getTasks(user.id);
      const currentTasks = tasksResponse.data || [];
      
      // If task has ID, update it, otherwise add it
      const updatedTasks = task.id 
        ? currentTasks.map(t => t.id === task.id ? { ...t, ...task } : t)
        : [...currentTasks, { ...task, id: `temp-${Date.now()}` }];
      
      // Save all tasks
      const { data, error, offline } = await saveTasks(user.id, updatedTasks);
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Update local user state
      setUser(prevUser => ({
        ...prevUser,
        tasks: data || updatedTasks
      }));
      
      return { success: true, task: task.id ? task : data.find(t => t.title === task.title) };
    } catch (error) {
      console.error('Error adding/updating task:', error);
      return { success: false, error: error.message };
    }
  };

  // Remove a task
  const removeTask = async (taskId) => {
    if (!user) return { success: false, error: 'No user logged in' };
    
    try {
      const { data, error, offline } = await deleteTask(user.id, taskId);
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Update local user state
      setUser(prevUser => ({
        ...prevUser,
        tasks: data || prevUser.tasks.filter(t => t.id !== taskId)
      }));
      
      return { success: true };
    } catch (error) {
      console.error('Error removing task:', error);
      // Still remove from local state even if server fails
      setUser(prevUser => ({
        ...prevUser,
        tasks: prevUser.tasks.filter(t => t.id !== taskId)
      }));
      return { success: true, offline: true };
    }
  };

  // Update tasks in database (batch operation)
  const updateTasks = async (tasks) => {
    if (!user) return { success: false, error: 'No user logged in' };
    
    try {
      const { data, error, offline } = await saveTasks(user.id, tasks);
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Update local user state
      setUser(prevUser => ({
        ...prevUser,
        tasks: data || tasks
      }));
      
      return { success: true, tasks: data || tasks };
    } catch (error) {
      console.error('Error updating tasks:', error);
      // Update local state anyway to prevent UI issues
      setUser(prevUser => ({
        ...prevUser,
        tasks: tasks
      }));
      return { success: true, error, offline: true };
    }
  };

  // Add study session to database
  const updateStudyData = async (studySession) => {
    if (!user) return { success: false, error: 'No user logged in' };
    
    try {
      const { data, error, offline } = await saveStudySession(user.id, studySession);
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Refresh study data
      const studyDataResponse = await getStudyData(user.id);
      const studyData = studyDataResponse.data || [];
      
      // Update local user state
      setUser(prevUser => ({
        ...prevUser,
        studyData: studyData,
        // If we got a new session back, add it to the study data
        ...(data && !studyData.find(s => s.id === data.id) ? {
          studyData: [data, ...(prevUser.studyData || [])]
        } : {})
      }));
      
      return { success: true };
    } catch (error) {
      console.error('Error updating study data:', error);
      // Add to local state anyway to prevent UI issues
      const newSession = {
        id: `temp-${Date.now()}`,
        ...studySession,
        date: studySession.date || new Date().toISOString()
      };
      
      setUser(prevUser => ({
        ...prevUser,
        studyData: [newSession, ...(prevUser.studyData || [])]
      }));
      
      return { success: true, offline: true };
    }
  };

  // Regular login function
  const login = async (email, password) => {
    try {
      // Input validation
      if (!email || !password) {
        return { 
          success: false, 
          error: 'Email and password are required' 
        };
      }
      
      const { data, error, offline } = await signIn(email, password);
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // If we didn't get user data back, something went wrong
      if (!data || !data.user) {
        console.error('Login returned no user data');
        return { 
          success: false, 
          error: 'Authentication failed. Please try again.' 
        };
      }
      
      setUser(data.user);
      
      // Check if onboarding is completed (with fallback to false)
      const onboardingDone = data.profile?.onboarding_completed || false;
      setOnboardingCompleted(onboardingDone);
      
      // Get tasks and study data with error handling
      if (data.user) {
        try {
          const [tasksResult, studyDataResult] = await Promise.all([
            getTasks(data.user.id),
            getStudyData(data.user.id)
          ]);
          
          // Update user with tasks and study data (handling null results)
          setUser(prevUser => ({
            ...prevUser,
            tasks: tasksResult?.data || [],
            studyData: studyDataResult?.data || []
          }));
        } catch (dataError) {
          // Log but don't fail login if data fetch fails
          console.error('Error fetching user data:', dataError);
        }
      }
      
      return { 
        success: true, 
        requiresOnboarding: !onboardingDone
      };
    } catch (error) {
      console.error('Login error:', error);
      return { 
        success: false, 
        error: error.message || 'Login failed. Please try again.' 
      };
    }
  };

  // Google login function
  const loginWithGoogle = async () => {
    try {
      const { data, error, offline } = await signInWithGoogle();
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Google login success but redirecting to OAuth
      return { success: true };
    } catch (error) {
      console.error('Google login error:', error);
      return { 
        success: false, 
        error: error.message || 'Google login failed. Please try again.' 
      };
    }
  };

  // Signup function
  const signup = async (userData) => {
    try {
      const { data, error, offline } = await signUp(
        userData.email, 
        userData.password,
        {
          name: userData.name,
          gender: userData.gender || 'neutral'
        }
      );
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      setUser(data.user);
      setIsNewUser(true);
      setOnboardingCompleted(false);
      
      return { success: true, requiresOnboarding: true };
    } catch (error) {
      console.error('Signup error:', error);
      return { 
        success: false, 
        error: error.message 
      };
    }
  };

  // Logout function
  const logout = async () => {
    try {
      const { error } = await signOut();
      
      if (error) throw error;
      
      setUser(null);
      setOnboardingCompleted(false);
      setIsOfflineMode(false);
      
      return { success: true };
    } catch (error) {
      console.error('Logout error:', error);
      return { 
        success: false, 
        error: error.message 
      };
    }
  };

  // Complete onboarding function
  const completeOnboarding = async (userPreferences) => {
    if (!user) return { success: false, error: 'No user logged in' };
    
    try {
      const { error, offline } = await saveUserProfile(user.id, {
        ...userPreferences,
        onboarding_completed: true
      });
      
      if (offline) setIsOfflineMode(true);
      
      if (error) throw error;
      
      // Update local state
      setUser(prevUser => ({
        ...prevUser,
        profile: {
          ...prevUser.profile,
          ...userPreferences,
          onboarding_completed: true
        }
      }));
      
      setOnboardingCompleted(true);
      setIsNewUser(false);
      
      return { success: true };
    } catch (error) {
      console.error('Error completing onboarding:', error);
      // Update local state anyway to prevent UI issues
      setUser(prevUser => ({
        ...prevUser,
        profile: {
          ...prevUser.profile,
          ...userPreferences,
          onboarding_completed: true
        }
      }));
      
      setOnboardingCompleted(true);
      setIsNewUser(false);
      
      return { success: true, offline: true };
    }
  };

  // Context value
  const value = {
    user,
    loading,
    isNewUser,
    onboardingCompleted,
    isOfflineMode,
    login,
    loginWithGoogle,
    signup,
    logout,
    updateUserData,
    updateTasks,
    addOrUpdateTask,
    removeTask,
    updateStudyData,
    completeOnboarding
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

// Custom hook to use the auth context
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export default AuthContext; 