import React, { useState, useEffect, lazy, useMemo, Suspense } from 'react';
import { Routes, Route, Navigate, useLocation, useNavigate } from 'react-router-dom';
import './App.css';
import { AuthProvider, useAuth } from './contexts/AuthContext';

// Context Providers
import { NotificationProvider } from './components/NotificationContext';
import { ThemeProvider, ThemeTransition } from './contexts/ThemeContext';
import { NavigationProvider } from './contexts/NavigationContext';
import { NeuralProvider } from './contexts/NeuralContext';

// Components
const DockBar = lazy(() => import('./components/DockBar'));

// Lazy loaded pages/views for better performance
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Tasks = lazy(() => import('./pages/Tasks'));
const Pomodoro = lazy(() => import('./pages/Pomodoro'));
const Books = lazy(() => import('./pages/Books'));
const Profile = lazy(() => import('./pages/Profile'));
const Calendar = lazy(() => import('./pages/Calendar'));
const Statistics = lazy(() => import('./pages/Statistics'));
const Leaderboard = lazy(() => import('./pages/Leaderboard'));
const Login = lazy(() => import('./pages/Login'));
const Signup = lazy(() => import('./pages/Signup'));
const Onboarding = lazy(() => import('./components/Onboarding'));
const Notes = lazy(() => import('./pages/Notes'));
const Flashcards = lazy(() => import('./pages/Flashcards'));
const Settings = lazy(() => import('./pages/Settings'));
const Contact = lazy(() => import('./pages/Contact'));
const Progress = lazy(() => import('./pages/Progress'));
const Community = lazy(() => import('./pages/Community'));
const EntryAnimation = lazy(() => import('./components/EntryAnimation'));

// Protected Route component
const ProtectedRoute = ({ children }) => {
  const { user, loading } = useAuth();

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  return children;
};

function AppContent() {
  const [isAndroid, setIsAndroid] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const [showEntryAnimation, setShowEntryAnimation] = useState(true);

  // Detect Android device on mount
  useEffect(() => {
    const userAgent = navigator.userAgent.toLowerCase();
    const isAndroidDevice = /android/i.test(userAgent);
    setIsAndroid(isAndroidDevice);
    
    // Auto-enable low performance mode on lower-end Android devices
    if (isAndroidDevice) {
      // Check if device is likely to be low-end by checking some performance indicators
      const isLowEndDevice = 
        !window.requestIdleCallback || 
        !window.requestAnimationFrame || 
        (navigator.deviceMemory && navigator.deviceMemory < 4);
      
      if (isLowEndDevice) {
        document.documentElement.classList.add('low-performance-mode');
      }
    }
    
    // Add Android-specific meta tags
    if (isAndroidDevice) {
      const viewportMeta = document.querySelector('meta[name="viewport"]');
      if (viewportMeta) {
        viewportMeta.content = 'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover';
      }
    }
  }, []);

  // Optimize scrolling behavior 
  useEffect(() => {
    // Ensure proper scrolling behavior only once during initial render
    document.body.style.overflow = 'auto';
    document.body.style.height = 'auto';
    document.documentElement.style.overflow = 'auto'; 
    document.documentElement.style.height = 'auto';
    
    // Add optimized event listeners for scroll performance
    const handleScroll = () => {
      // Only process scroll events when needed, using requestAnimationFrame
      if (!window.requestAnimationScrollUpdate) {
        window.requestAnimationScrollUpdate = true;
        window.requestAnimationFrame(() => {
          // Scroll optimization logic could go here if needed
          window.requestAnimationScrollUpdate = false;
        });
      }
    };
    
    window.addEventListener('scroll', handleScroll, { passive: true });
    
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const handleAnimationComplete = () => {
    setShowEntryAnimation(false);
  };

  // Memoized route rendering for improved performance
  const routes = useMemo(() => (
    <Suspense fallback={
      <div className="min-h-screen bg-gray-900 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
      </div>
    }>
      <Routes>
        {/* Public routes */}
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />
        
        {/* Protected routes */}
        <Route path="/" element={
          <ProtectedRoute>
            <Navigate to="/dashboard" replace />
          </ProtectedRoute>
        } />
        
        <Route path="/dashboard" element={
          <ProtectedRoute>
            <Dashboard key="dashboard" />
          </ProtectedRoute>
        } />
        
        <Route path="/tasks" element={
          <ProtectedRoute>
            <Tasks />
          </ProtectedRoute>
        } />
        
        <Route path="/pomodoro" element={
          <ProtectedRoute>
            <Pomodoro tasks={[]} />
          </ProtectedRoute>
        } />
        
        <Route path="/books" element={
          <ProtectedRoute>
            <Books />
          </ProtectedRoute>
        } />
        
        <Route path="/calendar" element={
          <ProtectedRoute>
            <Calendar />
          </ProtectedRoute>
        } />
        
        <Route path="/statistics" element={
          <ProtectedRoute>
            <Statistics />
          </ProtectedRoute>
        } />
        
        <Route path="/study" element={
          <ProtectedRoute>
            <Statistics />
          </ProtectedRoute>
        } />
        
        <Route path="/leaderboard" element={
          <ProtectedRoute>
            <Leaderboard />
          </ProtectedRoute>
        } />
        
        <Route path="/profile" element={
          <ProtectedRoute>
            <Profile />
          </ProtectedRoute>
        } />
        
        <Route path="/onboarding" element={
          <ProtectedRoute>
            <Onboarding />
          </ProtectedRoute>
        } />
        
        <Route path="/notes" element={
          <ProtectedRoute>
            <Notes />
          </ProtectedRoute>
        } />
        
        <Route path="/flashcards" element={
          <ProtectedRoute>
            <Flashcards />
          </ProtectedRoute>
        } />
        
        <Route path="/settings" element={
          <ProtectedRoute>
            <Settings />
          </ProtectedRoute>
        } />
        
        <Route path="/contact" element={
          <ProtectedRoute>
            <Contact />
          </ProtectedRoute>
        } />
        
        <Route path="/progress" element={
          <ProtectedRoute>
            <Progress />
          </ProtectedRoute>
        } />
        
        <Route path="/community" element={
          <ProtectedRoute>
            <Community />
          </ProtectedRoute>
        } />
        
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </Suspense>
  ), []);

  return (
    <ThemeProvider>
      <div className="min-h-screen bg-gray-900">
        {showEntryAnimation ? (
          <EntryAnimation onComplete={handleAnimationComplete} />
        ) : (
          <NavigationProvider>
            <NotificationProvider>
              <AuthProvider>
                <NeuralProvider>
                  <ThemeTransition>
                    <div className={`App relative min-h-screen overflow-x-hidden ${isAndroid ? 'android-device' : ''}`}>
                      {routes}
                      <Suspense fallback={null}>
                        <DockBar activeTab={location.pathname.substring(1) || 'dashboard'} setActiveTab={(tab) => navigate(`/${tab}`)} />
                      </Suspense>
                    </div>
                  </ThemeTransition>
                </NeuralProvider>
              </AuthProvider>
            </NotificationProvider>
          </NavigationProvider>
        )}
      </div>
    </ThemeProvider>
  );
}

export default AppContent;