// Helper function to check if Supabase is available
const checkSupabaseConnection = async () => {
  try {
    // Try a simpler operation - just checking auth status
    const { data } = await supabase.auth.getSession();
    return true; // If we got here, connection is working
  } catch (e) {
    console.error('Supabase connection check failed:', e);
    return false;
  }
};

// Auth helper functions
export const signUp = async (email, password, userData = {}) => {
  try {
    if (!await checkSupabaseConnection()) {
      return { data: { user: { email, id: `temp-${Date.now()}` } }, error: null, offline: true };
    }
    
    // Register user with Supabase Auth
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          name: userData.name || '',
          avatar_url: userData.avatarUrl || '',
        }
      }
    });

    if (authError) throw authError;
    
    // Create user profile in profiles table
    if (authData.user) {
      const { error: profileError } = await supabase
        .from('profiles')
        .insert({
          id: authData.user.id,
          email: email,
          name: userData.name || '',
          gender: userData.gender || 'neutral',
          major: userData.major || '',
          streak_days: 0,
          created_at: new Date(),
          updated_at: new Date(),
          avatar_url: userData.avatarUrl || '',
          onboarding_completed: false
        });
      
      if (profileError) {
        console.error('Error creating profile:', profileError);
      }
    }

    return { data: authData, error: null };
  } catch (error) {
    console.error('Signup error:', error);
    return { data: null, error };
  }
};

export const signIn = async (email, password) => {
  try {
    // Validate inputs
    if (!email || !password) {
      throw new Error('Email and password are required');
    }
    
    // Check if Supabase is accessible
    if (!await checkSupabaseConnection()) {
      console.log('Supabase unavailable, using offline mode');
      return {
        data: {
          user: { 
            email, 
            id: `temp-${Date.now()}`,
            profile: { 
              name: email.split('@')[0],
              onboarding_completed: true
            }
          }
        },
        error: null,
        offline: true
      };
    }
    
    // Create a promise that resolves after timeout
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error('Login request timed out')), 10000);
    });
    
    // Race the auth request against timeout
    const { data, error } = await Promise.race([
      supabase.auth.signInWithPassword({ email, password }),
      timeoutPromise
    ]);
    
    if (error) throw error;
    
    // Verify we have a user
    if (!data || !data.user) {
      throw new Error('Authentication failed');
    }
    
    // Fetch user profile data with timeout protection
    if (data.user) {
      try {
        const profilePromise = supabase
          .from('profiles')
          .select('*')
          .eq('id', data.user.id)
          .single();
          
        const profileTimeoutPromise = new Promise((_, reject) => {
          setTimeout(() => reject(new Error('Profile fetch timed out')), 8000);
        });
        
        const { data: profileData, error: profileError } = await Promise.race([
          profilePromise,
          profileTimeoutPromise
        ]);
        
        if (profileError) {
          console.error('Error fetching profile:', profileError);
          // Create default profile if none exists
          const defaultProfile = {
            id: data.user.id,
            name: data.user.email?.split('@')[0] || 'User',
            email: data.user.email,
            onboarding_completed: true,
            streak_days: 0
          };
          
          await supabase.from('profiles').upsert(defaultProfile);
          return { data: { ...data, profile: defaultProfile }, error: null };
        }
        
        return { data: { ...data, profile: profileData }, error: null };
      } catch (profileFetchError) {
        console.error('Profile fetch error:', profileFetchError);
        // Return default profile data to prevent UI errors
        const defaultProfile = {
          name: data.user.email?.split('@')[0] || 'User',
          email: data.user.email,
          onboarding_completed: true
        };
        return { data: { ...data, profile: defaultProfile }, error: null };
      }
    }
    
    return { data, error: null };
  } catch (error) {
    console.error('Login error:', error);
    return { data: null, error };
  }
};

export const signInWithGoogle = async () => {
  try {
    // Check if Supabase is accessible
    if (!await checkSupabaseConnection()) {
      return { 
        error: new Error('Cannot connect to database. Please try again later.') 
      };
    }
    
    // Create a promise that will reject after timeout
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error('Google login request timed out')), 15000);
    });
    
    // Race the OAuth request against timeout
    const { data, error } = await Promise.race([
      supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: window.location.origin
        }
      }),
      timeoutPromise
    ]);
    
    if (error) throw error;
    
    return { data, error: null };
  } catch (error) {
    console.error('Google login error:', error);
    return { data: null, error };
  }
};

export const signOut = async () => {
  try {
    // Check if we're in offline mode
    const currentUser = await supabase.auth.getUser();
    if (currentUser.error || !currentUser.data.user) {
      // Just clear local storage
      localStorage.removeItem('supabase.auth.token');
      return { error: null };
    }
    
    const { error } = await supabase.auth.signOut();
    if (error) throw error;
    return { error: null };
  } catch (error) {
    console.error('Signout error:', error);
    return { error };
  }
};

export const getCurrentUser = async () => {
  try {
    // Check if Supabase is accessible
    const isConnected = await checkSupabaseConnection();
    if (!isConnected) {
      const offlineUser = localStorage.getItem('offlineUser');
      if (offlineUser) {
        return { user: JSON.parse(offlineUser), error: null, offline: true };
      }
    }
    
    const { data: { user }, error } = await supabase.auth.getUser();
    
    if (error) throw error;
    
    // Get profile data
    if (user) {
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();
      
      if (profileError) {
        console.error('Error fetching profile:', profileError);
        // Create a default profile to prevent UI errors
        const defaultProfile = {
          id: user.id,
          name: user.email?.split('@')[0] || 'User',
          email: user.email,
          onboarding_completed: true,
          streak_days: 0
        };
        
        // Try to create the profile
        try {
          await supabase.from('profiles').upsert(defaultProfile);
        } catch (e) {
          console.error('Failed to create default profile', e);
        }
        
        return { user: { ...user, profile: defaultProfile }, error: null };
      }
      
      return { user: { ...user, profile: profileData || {} }, error: null };
    }
    
    return { user, error: null };
  } catch (error) {
    console.error('Get current user error:', error);
    return { user: null, error };
  }
};

// Session management
export const onAuthStateChange = (callback) => {
  try {
    const { data } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        // Get profile data when user signs in
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single();
          
        if (profileError) {
          console.error('Error fetching profile in auth state change:', profileError);
          
          // Create default profile if none exists
          const defaultProfile = {
            id: session.user.id,
            name: session.user.email?.split('@')[0] || 'User',
            email: session.user.email,
            onboarding_completed: true,
            streak_days: 0
          };
          
          try {
            await supabase.from('profiles').upsert(defaultProfile);
            callback({ ...session.user, profile: defaultProfile });
          } catch (e) {
            console.error('Failed to create default profile', e);
            callback({ ...session.user, profile: defaultProfile });
          }
        } else {
          callback({ ...session.user, profile: profileData || {} });
        }
      } else {
        callback(session?.user || null);
      }
    });
    
    return () => {
      if (data && typeof data.subscription?.unsubscribe === 'function') {
        data.subscription.unsubscribe();
      }
    };
  } catch (error) {
    console.error('Auth state change setup error:', error);
    return () => {}; // Return empty function for cleanup
  }
};

// User data functions
export const saveUserProfile = async (userId, profileData) => {
  try {
    // Check if offline mode
    if (!await checkSupabaseConnection()) {
      const offlineUser = localStorage.getItem('offlineUser');
      if (offlineUser) {
        const userData = JSON.parse(offlineUser);
        const updatedUser = {
          ...userData,
          profile: {
            ...userData.profile,
            ...profileData,
            updated_at: new Date().toISOString()
          }
        };
        localStorage.setItem('offlineUser', JSON.stringify(updatedUser));
      }
      return { data: profileData, error: null, offline: true };
    }
    
    // Update auth metadata
    await supabase.auth.updateUser({
      data: {
        name: profileData.name || '',
        avatar_url: profileData.avatarUrl || '',
      }
    });
    
    // Update profile table with complete profile data
    const { data, error } = await supabase
      .from('profiles')
      .upsert({
        id: userId,
        ...profileData,
        updated_at: new Date(),
      }, { onConflict: 'id' });
      
    if (error) throw error;
    return { data, error: null };
  } catch (error) {
    console.error('Save profile error:', error);
    // Return the profile data anyway to update the UI
    return { data: profileData, error, offline: true };
  }
};

// Tasks management
export const saveTasks = async (tasks) => {
  try {
    if (!tasks || !Array.isArray(tasks) || tasks.length === 0) {
      return { success: true, data: [] };
    }
    
    // Make sure all tasks have a user_id
    const userId = tasks[0].user_id;
    if (!userId) {
      throw new Error('User ID is required for tasks');
    }
    
    console.log(`Saving ${tasks.length} tasks for user ${userId}`);
    
    // Process each task individually to ensure proper error handling
    const savedTasks = [];
    const errors = [];
    
    for (const task of tasks) {
      try {
        // Check if the task has an ID that doesn't start with "temp-"
        if (task.id && !task.id.startsWith('temp-')) {
          // This is an existing task, update it
          const { data, error } = await supabase
            .from('tasks')
            .update({
              title: task.title,
              description: task.description || '',
              priority: task.priority || 'medium',
              due_date: task.due_date || null,
              completed: task.completed || false,
              updated_at: new Date().toISOString()
            })
            .eq('id', task.id)
            .eq('user_id', userId)
            .select();
          
          if (error) throw error;
          
          if (data && data.length > 0) {
            savedTasks.push(data[0]);
          } else {
            savedTasks.push(task);
          }
        } else {
          // This is a new task or has a temporary ID, insert it
          // Remove temp ID if it exists
          const { id, ...taskWithoutTempId } = task.id?.startsWith('temp-') 
            ? task 
            : task;
          
          const { data, error } = await supabase
            .from('tasks')
            .insert({
              ...taskWithoutTempId,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            })
            .select();
          
          if (error) throw error;
          
          if (data && data.length > 0) {
            savedTasks.push(data[0]);
          }
        }
      } catch (taskError) {
        console.error(`Error saving task: ${taskError.message}`, task);
        errors.push({ task, error: taskError.message });
        // Continue with other tasks
        savedTasks.push(task); // Keep the original for the UI
      }
    }
    
    console.log(`Successfully saved ${savedTasks.length} tasks, with ${errors.length} errors`);
    
    if (errors.length > 0 && errors.length === tasks.length) {
      // All tasks failed to save
      throw new Error('Failed to save any tasks');
    }
    
    return { 
      success: true, 
      data: savedTasks,
      errors: errors.length > 0 ? errors : null 
    };
  } catch (error) {
    console.error('Error saving tasks:', error);
    return { success: false, error: error.message };
  }
};

// Delete a task
export const deleteTask = async (userId, taskId) => {
  try {
    // Check if offline mode
    if (!await checkSupabaseConnection()) {
      const tasksJson = localStorage.getItem(`tasks_${userId}`);
      if (tasksJson) {
        const tasks = JSON.parse(tasksJson);
        const updatedTasks = tasks.filter(task => task.id !== taskId);
        localStorage.setItem(`tasks_${userId}`, JSON.stringify(updatedTasks));
        return { data: updatedTasks, error: null, offline: true };
      }
      return { data: [], error: null, offline: true };
    }
    
    const { error } = await supabase
      .from('tasks')
      .delete()
      .eq('id', taskId)
      .eq('user_id', userId);
      
    if (error) throw error;
    
    // Get remaining tasks
    return await getTasks(userId);
  } catch (error) {
    console.error('Delete task error:', error);
    return { data: null, error };
  }
};

