// Update user streak
const updateUserStreak = async (userId) => {
  try {
    // Check if offline mode
    if (!await checkSupabaseConnection()) {
      return { streak: 1 };
    }
    
    // Get user profile
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('streak_days, last_study_date')
      .eq('id', userId)
      .single();
      
    if (profileError) throw profileError;
    
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    const lastStudyDate = profile.last_study_date 
      ? new Date(profile.last_study_date) 
      : null;
      
    if (lastStudyDate) {
      lastStudyDate.setHours(0, 0, 0, 0);
    }
    
    let newStreak = profile.streak_days || 0;
    
    // If studied today already, don't update
    if (lastStudyDate && lastStudyDate.getTime() === today.getTime()) {
      return { streak: newStreak };
    }
    
    // Check if last study was yesterday
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    
    if (!lastStudyDate || lastStudyDate.getTime() < yesterday.getTime()) {
      // Streak broken, start new streak
      newStreak = 1;
    } else if (lastStudyDate.getTime() === yesterday.getTime()) {
      // Continue streak
      newStreak += 1;
    }
    
    // Update profile
    const { error } = await supabase
      .from('profiles')
      .update({
        streak_days: newStreak,
        last_study_date: today.toISOString(),
        updated_at: new Date()
      })
      .eq('id', userId);
      
    if (error) throw error;
    
    return { streak: newStreak };
  } catch (error) {
    console.error('Update streak error:', error);
    return { streak: 0 };
  }
};

